<div class="admin-page-heading"><div><span class="admin-eyebrow">CLIENT FEEDBACK</span><p>Only publish genuine customer feedback with permission.</p></div><a class="admin-button" href="<?= e(url('/admin/testimonials/create')) ?>">＋ Add Testimonial</a></div><section class="admin-panel"><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>CLIENT</th><th>TESTIMONIAL</th><th>STATUS</th><th>ACTIONS</th></tr></thead><tbody><?php foreach($testimonials as $t): ?><tr><td><strong><?= e($t['customer_name']) ?></strong><small><?= e($t['role_label']) ?></small></td><td><?= e(mb_strimwidth($t['quote'],0,130,'…')) ?></td><td><span class="status <?= $t['is_published']?'status-completed':'status-closed' ?>"><?= $t['is_published']?'Published':'Hidden' ?></span></td><td class="actions-cell"><a class="table-action" href="<?= e(url('/admin/testimonials/'.$t['id'].'/edit')) ?>">Edit</a><form method="post" action="<?= e(url('/admin/testimonials/'.$t['id'].'/delete')) ?>" data-confirm="Delete this testimonial?"><?= csrf_field() ?><button class="table-danger" type="submit">Delete</button></form></td></tr><?php endforeach; ?></tbody></table></div><?php if(!$testimonials): ?><div class="admin-empty"><span>❝</span><h3>No testimonials added</h3><p>Publish customer feedback only after it has been verified and approved.</p></div><?php endif; ?></section>
